import{_ as a,o as l,c as r,a2 as t}from"./chunks/framework.BXA5Pi9t.js";const C=JSON.parse('{"title":"Ceph Day CERN 2019: Speaker Panel Q/A","description":"","frontmatter":{"title":"Ceph Day CERN 2019: Speaker Panel Q/A","date":"2020-08-25T00:00:00.000Z","updated":"2020-08-26T00:00:00.000Z","tags":["Ceph","分布式存储","Ceph Dashboard","CRUSH 算法","高可用性"],"categories":["视频总结"],"outline":"deep"},"headers":[],"relativePath":"posts/2020/Ceph_Day_CERN_2019_-_Speaker_Panel_Q_A.md","filePath":"posts/2020/Ceph_Day_CERN_2019_-_Speaker_Panel_Q_A.md","lastUpdated":1780459816000}'),i={name:"posts/2020/Ceph_Day_CERN_2019_-_Speaker_Panel_Q_A.md"};function h(o,e,p,s,n,d){return l(),r("div",null,[...e[0]||(e[0]=[t('<h3 id="会议纪要" tabindex="-1">会议纪要 <a class="header-anchor" href="#会议纪要" aria-label="Permalink to &quot;会议纪要&quot;">​</a></h3><h4 id="会议主题-ceph存储系统功能讨论与用户反馈" tabindex="-1">会议主题：Ceph存储系统功能讨论与用户反馈 <a class="header-anchor" href="#会议主题-ceph存储系统功能讨论与用户反馈" aria-label="Permalink to &quot;会议主题：Ceph存储系统功能讨论与用户反馈&quot;">​</a></h4><h4 id="参会人员-ceph专家、csc代表peter-reverend、ceph集群操作员等" tabindex="-1">参会人员：Ceph专家、CSC代表Peter Reverend、Ceph集群操作员等 <a class="header-anchor" href="#参会人员-ceph专家、csc代表peter-reverend、ceph集群操作员等" aria-label="Permalink to &quot;参会人员：Ceph专家、CSC代表Peter Reverend、Ceph集群操作员等&quot;">​</a></h4><h4 id="会议时间-具体日期" tabindex="-1">会议时间：[具体日期] <a class="header-anchor" href="#会议时间-具体日期" aria-label="Permalink to &quot;会议时间：[具体日期]&quot;">​</a></h4><h4 id="会议地点-具体地点" tabindex="-1">会议地点：[具体地点] <a class="header-anchor" href="#会议地点-具体地点" aria-label="Permalink to &quot;会议地点：[具体地点]&quot;">​</a></h4><h4 id="主要议题及讨论内容" tabindex="-1">主要议题及讨论内容： <a class="header-anchor" href="#主要议题及讨论内容" aria-label="Permalink to &quot;主要议题及讨论内容：&quot;">​</a></h4><ol><li><p><strong>Ceph Dashboard支持多CRUSH规则的问题</strong></p><ul><li>讨论了Ceph Dashboard是否支持多CRUSH规则，并确认可以在Dashboard中修改池属性，但创建新CRUSH规则的功能尚不确定。</li><li>强调了Ceph团队正在不断更新和优化Dashboard的基本功能。</li></ul></li><li><p><strong>Safe Day Nordic活动信息</strong></p><ul><li>Peter Reverend询问Safe Day Nordic活动的举办地点和时间，确认活动将在挪威、瑞典、冰岛、芬兰等地举行，预计在11月底。</li></ul></li><li><p><strong>Ceph集群的Telemetry功能启用情况</strong></p><ul><li>调查了参会者中Ceph集群是否启用了Telemetry功能，讨论了数据隐私和网络安全等顾虑。</li><li>提到Telemetry数据目前被发送到上游Ceph实验室的机器，存储在PostgreSQL数据库中，只有少数开发人员有权访问。</li></ul></li><li><p><strong>CephFS的多站点使用情况</strong></p><ul><li>讨论了CephFS在多站点环境中的使用情况，强调需要特别注意网络链接的质量和服务的实时性。</li></ul></li><li><p><strong>Ceph集群的运行和配置问题</strong></p><ul><li>讨论了Ceph集群的运行情况和配置问题，包括启用Telemetry功能的具体操作和配置HTTP代理的可能性。</li></ul></li></ol><h4 id="决定事项" tabindex="-1">决定事项： <a class="header-anchor" href="#决定事项" aria-label="Permalink to &quot;决定事项：&quot;">​</a></h4><ul><li>确认Ceph Dashboard支持多CRUSH规则的修改，但创建新规则的功能尚不确定。</li><li>确认Safe Day Nordic活动的举办地点和时间。</li><li>讨论了Telemetry功能的启用情况和相关顾虑，强调数据安全和隐私保护。</li><li>讨论了CephFS在多站点环境中的使用和注意事项。</li></ul><h4 id="后续行动计划" tabindex="-1">后续行动计划： <a class="header-anchor" href="#后续行动计划" aria-label="Permalink to &quot;后续行动计划：&quot;">​</a></h4><ul><li>进一步确认Ceph Dashboard中创建新CRUSH规则的功能，并更新相关文档。</li><li>继续优化Telemetry功能，解决用户的顾虑，并确保数据安全和隐私保护。</li><li>提供更多关于CephFS多站点使用的指导和最佳实践。</li><li>更新和完善Ceph相关文档，包括Telemetry功能的详细说明和配置指南。</li></ul><h4 id="备注" tabindex="-1">备注： <a class="header-anchor" href="#备注" aria-label="Permalink to &quot;备注：&quot;">​</a></h4><ul><li>会议中提到的关键词和术语包括Ceph Dashboard、CRUSH rules、Telemetry、CephFS、RADOS cluster等。</li><li>会议记录了参会者的反馈和建议，为Ceph的进一步开发和优化提供了重要参考。</li></ul>',13)])])}const c=a(i,[["render",h]]);export{C as __pageData,c as default};
